    40  size_t ptls_minicrypto_asn1_decode_private_key(ptls_asn1_pkcs8_private_key_t *pkey, int *decode_error,
    41                                                 ptls_minicrypto_log_ctx_t *log_ctx)
    42  {
    43      uint8_t *bytes = pkey->vec.base;
    44      size_t bytes_max = pkey->vec.len;
    45
    46      /* read the ASN1 messages */
    47      size_t byte_index = 0;
    48      uint32_t seq0_length = 0;
    49      size_t last_byte0;
    50      uint32_t seq1_length = 0;
    51      size_t last_byte1 = 0;
    52      uint32_t oid_length;
    53      size_t last_oid_byte;
    54      uint32_t key_data_length;
    55      size_t key_data_last;
    56
    57      /* start with sequence */
    58      byte_index = ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, 0x30, &seq0_length, NULL, &last_byte0,
    59                                                          decode_error, log_ctx);
    60
    61      if (*decode_error == 0 && bytes_max != last_byte0) {
    62          byte_index = ptls_asn1_error_message("Length larger than message", bytes_max, byte_index, 0, log_ctx);
    63          *decode_error = PTLS_ERROR_BER_EXCESSIVE_LENGTH;
    64      }
    65
    66      if (*decode_error == 0) {
    67          /* get first component: version, INTEGER, expect value 0 */
    68          if (byte_index + 3 > bytes_max) {
    69              byte_index = ptls_asn1_error_message("Cannot find key version", bytes_max, byte_index, 0, log_ctx);
    70              *decode_error = PTLS_ERROR_INCORRECT_PEM_KEY_VERSION;
    71          } else if (bytes[byte_index] != 0x02 || bytes[byte_index + 1] != 0x01 || bytes[byte_index + 2] != 0x00) {
    72              *decode_error = PTLS_ERROR_INCORRECT_PEM_KEY_VERSION;
    73              byte_index = ptls_asn1_error_message("Incorrect PEM Version", bytes_max, byte_index, 0, log_ctx);
    74          } else {
    75              byte_index += 3;
    76              if (log_ctx != NULL) {
    77                  log_ctx->fn(log_ctx->ctx, "   Version = 1,\n");
    78              }
    79          }
    80      }
    81
    82      if (*decode_error == 0) {
    83          /* open embedded sequence */
    84          byte_index = ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, 0x30, &seq1_length, NULL, &last_byte1,
    85                                                              decode_error, log_ctx);
    86      }
    87
    88      if (*decode_error == 0) {
    89          if (log_ctx != NULL) {
    90              log_ctx->fn(log_ctx->ctx, "   Algorithm Identifier:\n");
    91          }
    92          /* get length of OID */
    93          byte_index = ptls_asn1_get_expected_type_and_length(bytes, last_byte1, byte_index, 0x06, &oid_length, NULL, &last_oid_byte,
    94                                                              decode_error, log_ctx);
    95
    96          if (*decode_error == 0) {
    97              if (log_ctx != NULL) {
    98                  /* print the OID value */
    99                  log_ctx->fn(log_ctx->ctx, "      Algorithm:");
   100                  ptls_asn1_dump_content(bytes + byte_index, oid_length, 0, log_ctx);
   101                  log_ctx->fn(log_ctx->ctx, ",\n");
   102              }
   103              pkey->algorithm_index = byte_index;
   104              pkey->algorithm_length = oid_length;
   105              byte_index += oid_length;
   106          }
   107      }
   108
   109      if (*decode_error == 0) {
   110          /* get parameters, ANY */
   111          if (log_ctx != NULL) {
   112              log_ctx->fn(log_ctx->ctx, "      Parameters:\n");
   113          }
   114
   115          pkey->parameters_index = byte_index;
   116
   117          pkey->parameters_length =
   118              (uint32_t)ptls_asn1_validation_recursive(bytes + byte_index, last_byte1 - byte_index, decode_error, 2, log_ctx);
   119
   120          byte_index += pkey->parameters_length;
   121
   122          if (log_ctx != NULL) {
   123              log_ctx->fn(log_ctx->ctx, "\n");
   124          }
   125          /* close sequence */
