   286                  ret = 0;
   287              } else {
   288                  ret = PTLS_ERROR_INCORRECT_BASE64;
   289              }
   290              break;
   291          } else {
   292              ret = ptls_base64_decode(line, &state, buf);
   293          }
   294      }
   295
   296      return ret;
